            "topicId": "physics-9702-topic-13",
            "sectionCode": "13.1",
            "outcomeNumber": 2,
            "officialText": "represent a gravitational field by means of field lines",
            "officialPage": 26,
            "sourceSha256": "468F4A01B9459701E5B21A010FDE12538AA16413A25496C311F7CE6FDD585E8C",
