const freeze = (value) => Object.freeze(value)

export function latestSyllabusForRoute({ routeId, code, stage, paperComponents = [] } = {}) {
  const source = CAMBRIDGE_LATEST_SYLLABUS_CATALOG[String(code || '')]
  if (!source) return null
  const selected = new Set((paperComponents || []).map(Number))
  const topics = source.topics.filter((topic) => {
    const stageMatches = stage === 'IGCSE' ? topic.stage === 'IGCSE' : topic.stage === stage || topic.stage === 'AS/A2'
    return stageMatches && topic.components.some((component) => selected.has(Number(component)))
  }).map((topic) => freeze({
    ...topic, routeId, syllabusVersion: source.syllabusVersion,
    points: freeze(topic.points.map((point) => freeze({ ...point }))),
    components: freeze([...topic.components]),
  }))
  return freeze({
    board: source.board, code: source.code, routeId, syllabusVersion: source.syllabusVersion, officialUrl: source.officialUrl, sourceSha256: source.sourceSha256, extraction: source.extraction,
    assessmentComponents: freeze(source.assessmentComponents.filter((item) => selected.has(Number(item.component))).map((item) => freeze({ ...item, stage: item.stage === 'AS/A2' ? stage : item.stage }))),
    componentScope: freeze(source.assessmentComponents.filter((item) => selected.has(Number(item.component))).map((item) => freeze({ component: item.component, stage: item.stage === 'AS/A2' ? stage : item.stage, track: item.track || 'theory', label: item.label }))),
    topics: freeze(topics), points: freeze(topics.flatMap((topic) => topic.points)),
  })
}
